<div class="dashboard-wrap"><h1><?=$product?'Edit':'Add'?> Product</h1><?=form_open($product?'admin/products/edit/'.$product->id:'admin/products/add')?><div class="form-group"><label>Name</label><input name="name" value="<?=html_escape($product?$product->name:'')?>" required></div><div class="form-group"><label>Category</label><input name="category" value="<?=html_escape($product?$product->category:'')?>"></div><div class="form-group"><label>Description</label><textarea name="description"><?=html_escape($product?$product->description:'')?></textarea></div><div class="form-group"><label>Price</label><input type="number" step="0.01" name="price" value="<?=html_escape($product?$product->price:'')?>" required></div><div class="form-group"><label>Old Price</label><input type="number" step="0.01" name="old_price" value="<?=html_escape($product?$product->old_price:'')?>"></div><div class="form-group"><label>Image filename</label><input name="image" value="<?=html_escape($product?$product->image:'l1.png')?>" required></div><div class="form-group"><label>Stock</label><input type="number" name="stock" value="<?=html_escape($product?$product->stock:10)?>"></div><label><input type="checkbox" name="is_featured" value="1" <?=$product&&$product->is_featured?'checked':''?>> Featured</label><br><br><button class="btn btn-primary">Save Product</button></form></div>
